/**             
 * Builds payloads for WaSOS geo operations:                                                                                                                                                     
 * Output 1: GeoJSON location chat message
 * Output 2: Geo marker                                                                                                                                                                          
 */
const geo = msg.metadata.geo;
const target = msg.metadata.target;
const source = msg.metadata.source;
const utils = global.get("utils");
const base_url = global.get("parat_bridge").base_urls.wasos;
const callsign = `${utils.build_callsign(source)} ${msg.entry.author}`;

// Group UUID from WaSOS login response                                                                                                                                                          
const groups = target.client_specific.group;
const groupId = Array.isArray(groups) && groups.length > 0
    ? groups[0]
    : null;

if (!groupId) {
    node.warn("No WaSOS group UUID available for geo operations");
    return null;
}

// Output 1: GeoJSON location in chat                                                                                                                                                            
const geoFeature = {
    type: "Feature",
    properties: {
        objecttype: "chat",
        description: geo.name,
        color: "blue",
        username: callsign,
        groups: [groupId],
        id: callsign
    },
    geometry: {
        type: "Point",
        coordinates: [geo.lng, geo.lat]
    }
};

const chatMsg = {
    metadata: msg.metadata,
    entry: msg.entry,
    url: base_url + "/api/chat/messages/"
        + target.client_specific.chatroom_name,
    headers: {
        "x-api-key": target.api_key,
        "Content-Type": "application/json"
    },
    payload: {
        content: JSON.stringify(geoFeature),
        callsign: callsign,
        isLocation: true,
        replyMessageId: null,
        files: []
    }
};

// Output 2: Marker on map
const markerMsg = {
    metadata: msg.metadata,
    entry: msg.entry,
    url: base_url + "/api/geo/markers",
    headers: {
        "x-api-key": target.api_key,
        "Content-Type": "application/json"
    },
    payload: {
        classification: "U",
        collaborative: false,
        color: "red",
        description: geo.name,
        files: [],
        geometry: {
            type: "Point",
            coordinates: [geo.lng, geo.lat]
        },
        groups: [groupId],
        objectType: "marker"
    }
};

return [[chatMsg], [markerMsg]];
